import sys; sys.path.insert(0,'src')
from mlir.parser import parse
from k_circt import find_hw_module, SemanticError
src='''
module {
  hw.module @A(in %a: i4, out o: i4) { hw.output %a : i4 }
  hw.module @B(in %a: i4, out o: i4) { hw.output %a : i4 }
}
'''
top = parse(src)
print('root op name:', top.name)
print('by name B ->', find_hw_module(top,'B').attributes['sym_name'].value)
print('by name A ->', find_hw_module(top,'A').attributes['sym_name'].value)
try: find_hw_module(top,'C')
except SemanticError as e: print('C ->', e)
a = find_hw_module(top,'A')
print('short-circuit: find_hw_module(A_op, \"B\") ->', find_hw_module(a,'B').attributes['sym_name'].value)
print('walk from A_op finds:', [o.name for o in a.walk_ops() if o.name.endswith(\"module\")])
